#!/usr/bin/env python3
"""Draft _work/policies.txt for a candidate from the built constraint ledger.

Status rule (deterministic draft, then overridden by _work/policy_overrides.txt):
  - at least one ORACLE_LINKED constraint citing the policy -> MATCHED
  - otherwise -> NOT_EVIDENCED
Overrides file lines: '<ID> <STATUS> ;; <note appended to search notes>' (STATUS '=' keeps the draft status).
Search notes record where evidence was found (files, constraint counts) and the search performed.
"""
import argparse
import json
from collections import defaultdict
from pathlib import Path


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--root', type=Path, default=Path('.'))
    ap.add_argument('--candidate', required=True)
    a = ap.parse_args()
    root = a.root.resolve()
    cand = a.candidate
    out = root / 'stage_A' / 'primary' / cand
    work = out / '_work'
    inv = json.loads((root / 'inputs' / cand / 'source' / 'inventory.json').read_text(encoding='utf-8-sig'))
    sh = json.loads((root / 'inputs' / cand / 'source' / 'shared-research-invariants.json').read_text(encoding='utf-8-sig'))
    pols = [p for g in inv['policygroups'] for p in g['policies']] + list(sh['invariants'])
    cons = [json.loads(l) for l in (out / 'constraints.jsonl').read_text(encoding='utf-8').splitlines() if l.strip()]
    segs = {json.loads(l)['segment_id']: json.loads(l) for l in (out / 'coverage_ranges.jsonl').read_text(encoding='utf-8').splitlines() if l.strip()}
    nfiles = sum(1 for l in (out / 'files.jsonl').read_text(encoding='utf-8').splitlines() if l.strip())
    ol = defaultdict(list)
    ex = defaultdict(list)
    for c in cons:
        for p in c['policy_ids']:
            (ol if c['origin'] == 'ORACLE_LINKED' else ex)[p].append(c)
    overrides = {}
    of = work / 'policy_overrides.txt'
    if of.is_file():
        for raw in of.read_text(encoding='utf-8').splitlines():
            if not raw.strip() or raw.lstrip().startswith('#'):
                continue
            head, _, note = raw.partition(';;')
            pid, st = head.split()[:2]
            overrides[pid] = (st, note.strip())
    lines = ['# Generated by _tools/gen_policies.py from the constraint ledger plus _work/policy_overrides.txt.']
    for p in pols:
        pid = p['id']
        cs = ol[pid]
        files = sorted({segs[s]['path'].replace('output/template/', '') for c in cs for s in c['evidence_segment_ids']})
        status = 'MATCHED' if cs else 'NOT_EVIDENCED'
        if cs:
            note = (f'Forward search for every clause of "{p["normalized_policy"][:160]}" over all {nfiles} active files, '
                    f'cross-checked with the full reverse annotation. {len(cs)} oracle-linked atomic constraint(s) found in: '
                    + '; '.join(files[:12]) + ('; ...' if len(files) > 12 else '') + '.')
        else:
            note = (f'Forward search for "{p["normalized_policy"][:160]}" over all {nfiles} active files and full reverse '
                    'annotation found no oracle-linked implementation.')
        if pid in overrides:
            st, extra = overrides[pid]
            if st != '=':
                status = st
            if extra:
                note += ' ' + extra
        lines.append(f'{pid} {status} ;; {note}')
    (work / 'policies.txt').write_text('\n'.join(lines) + '\n', encoding='utf-8')
    print(f'wrote {len(pols)} policy lines')


if __name__ == '__main__':
    main()
